local function loadScript(url)
	StatusLabel.Text = "loading..."
	fadeOutAndDestroy(function()
		local success, err = pcall(function()
			local commitHash = "main"
			pcall(function()
				local apiRes = httpGet("https://api.github.com/repos/hubivory/IvoryHub/commits?per_page=1")
				if apiRes then
					local hash = apiRes:match('"sha":"(%w+)"')
					if hash then commitHash = hash end
				end
			end)

			local LIB_SRC = getgenv()._IvoryLibSrc
			if not LIB_SRC then
				LIB_SRC = httpGet("https://raw.githubusercontent.com/hubivory/IvoryHub/main/library/IvoryHubLibrary.lua")
			end
			local genv = getgenv()
			genv._IvoryLibSrc = LIB_SRC

			local fetchUrl = GITHUB_RAW .. commitHash .. "/" .. url
			local content = httpGet(fetchUrl)
			local fetchBad = not content or #content == 0
				or content:sub(1, 15) == "404: Not Found"
				or content:find("<!DOCTYPE", 1, true) ~= nil
				or content:find("<html", 1, true) ~= nil
			if fetchBad then
				content = EMBEDDED_SCRIPTS and EMBEDDED_SCRIPTS[url]
				if content then print("[Ivory] 404 from GitHub, using embedded copy: " .. tostring(url)) end
			end
			if not content or #content == 0 then error("HTTP fetch failed (404, no embedded copy): " .. tostring(fetchUrl)) end

			if content:byte(1) == 0xEF and content:byte(2) == 0xBB and content:byte(3) == 0xBF then
				content = content:sub(4)
			end

			local fn, loadErr = loadstring(content)
			if not fn then error("Compile error: " .. tostring(loadErr)) end
			fn()
		end)

		if success then
			print("[Ivory] Loaded successfully!")
		else
			warn("[Ivory] Failed to load:", err)
		end
	end)
end

