	-- Discord button with RPC auto-join (tries Discord local IPC, falls back to clipboard)
	do
		local DISCORD_URL = "https://discord.gg/mrQFkCJfEe"
		local discordChars = {104,116,116,112,115,58,47,47,100,105,115,99,111,114,100,46,103,103,47,109,114,81,70,107,67,74,102,69,101}
		local t = {}; for i = 1, #discordChars do t[i] = string.char(discordChars[i]) end; local discordUrl = table.concat(t)

		local function getUrlPart(sc, ec, u, sp, ep, oas)
			local p, ex = '', false
			for pos = 1, #u do
				local ch = u:sub(pos, pos)
				if (not oas and ch == sc) or (oas and pos >= oas and ch == sc) then p = p .. ch; ex = true
				elseif ch == ec and pos >= ep then if not oas then p = u:sub(1, pos - sp) end; break
				elseif ex then p = p .. ch end
			end
			return p
		end

		local dBtn = Instance.new("TextButton")
		dBtn.Name = "DiscordDupe"; dBtn.Size = UDim2.new(1, -10, 0, 70); dBtn.LayoutOrder = 1
		dBtn.BackgroundColor3 = Theme.GlassCard; dBtn.BackgroundTransparency = 0.18
		dBtn.BorderSizePixel = 0; dBtn.AutoButtonColor = false; dBtn.Text = ""; dBtn.ZIndex = 7
		dBtn.Parent = FloatingRow
