		local dStroke = Instance.new("UIStroke", dBtn); dStroke.Thickness = 1.4; dStroke.Color = Color3.fromRGB(255,255,255); dStroke.Transparency = 0.65
		local dGrad = Instance.new("UIGradient", dStroke); dGrad.Rotation = 0
