		dGrad.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.3), NumberSequenceKeypoint.new(0.5, 0.6), NumberSequenceKeypoint.new(1, 0.3)})
		local dIcon = Instance.new("Frame", dBtn); dIcon.Size = UDim2.fromOffset(18,18); dIcon.Position = UDim2.new(0,14,0,15); dIcon.BackgroundTransparency = 1; dIcon.ZIndex = 9
		IconChat(dIcon, Theme.Discord)
		local dGlow = Instance.new("Frame", dBtn); dGlow.Size = UDim2.fromOffset(28,28); dGlow.Position = UDim2.new(0,9,0,10); dGlow.BackgroundColor3 = Theme.Discord; dGlow.BackgroundTransparency = 0.85; dGlow.BorderSizePixel = 0; dGlow.ZIndex = 8
		Instance.new("UICorner", dGlow).CornerRadius = UDim.new(1, 0)
		local dTxt = Instance.new("TextLabel", dBtn); dTxt.Size = UDim2.new(1,-38,0,14); dTxt.Position = UDim2.new(0,36,0,12); dTxt.BackgroundTransparency = 1; dTxt.Text = "Discord (dupe)"; dTxt.TextColor3 = Theme.TextPrimary; dTxt.Font = Enum.Font.GothamMedium; dTxt.TextSize = 11; dTxt.TextXAlignment = Enum.TextXAlignment.Left; dTxt.ZIndex = 9
		local dSub = Instance.new("TextLabel", dBtn); dSub.Size = UDim2.new(1,-38,0,12); dSub.Position = UDim2.new(0,36,0,26); dSub.BackgroundTransparency = 1; dSub.Text = "click to join"; dSub.TextColor3 = Theme.TextTertiary; dSub.Font = Enum.Font.Gotham; dSub.TextSize = 9; dSub.TextXAlignment = Enum.TextXAlignment.Left; dSub.ZIndex = 9

		task.spawn(function() while dBtn.Parent do dGrad.Rotation = (dGrad.Rotation + 0.5) % 360; RunService.Heartbeat:Wait() end end)
		dBtn.MouseEnter:Connect(function() tw(dBtn, EASE_QUICK, {BackgroundTransparency = 0.08}); tw(dStroke, EASE_QUICK, {Transparency = 0.3}); tw(dGlow, EASE_QUICK, {BackgroundTransparency = 0.7}) end)
		dBtn.MouseLeave:Connect(function() tw(dBtn, EASE_QUICK, {BackgroundTransparency = 0.18}); tw(dStroke, EASE_QUICK, {Transparency = 0.65}); tw(dGlow, EASE_QUICK, {BackgroundTransparency = 0.85}) end)

		dBtn.MouseButton1Click:Connect(function()
			local rpcOk = pcall(function()
				game.HttpService:RequestAsync({
					Url = "http://127.0.0.1:6463/rpc?v=1",
					Method = 'POST',
					Headers = { ['Origin'] = getUrlPart('h','p',discordUrl,2,5):sub(1,-4)..'.com', ['Content-Type'] = 'application/json' },
					Body = game.HttpService:JSONEncode({ cmd = 'INVITE_BROWSER', args = {code = getUrlPart('p','2',discordUrl,10,35,6)}, nonce = game.HttpService:GenerateGUID(false):lower() })
				})
			end)
			local orig = dTxt.Text
			if rpcOk then
				dTxt.Text = "Opening Discord..."; dTxt.TextColor3 = Theme.Success; dSub.Text = "check your Discord"
			else
				pcall(function() setclipboard(DISCORD_URL) end)
				dTxt.Text = "Copied!"; dTxt.TextColor3 = Theme.Success; dSub.Text = "saved to clipboard"
			end
			tw(dGrad, EASE_QUICK, {Rotation = 180})
			task.delay(1.5, function() dTxt.Text = orig; dTxt.TextColor3 = Theme.TextPrimary; dSub.Text = "click to join"; tw(dGrad, EASE_QUICK, {Rotation = 360}) end)
		end)
	end
